s=s.replace("function teamObjects(comp){const dbAll=state.teams.filter(t=>!comp||t.competition===comp);if(dbAll.length)return dbAll.filter(t=>t.enabled!==false);return catalog.filter(t=>!comp||t.competition===comp);}","""function teamCompetitions(t){return Array.isArray(t.competitions)&&t.competitions.length?t.competitions:(t.competition?[t.competition]:[])}
function isCompActive(comp){const a=state.season?.activeCompetitions;return !Array.isArray(a)||!a.length||a.includes(comp)}
function teamObjects(comp){const source=state.teams.length?state.teams:catalog;return source.filter(t=>t.enabled!==false&&(!comp||teamCompetitions(t).includes(comp)))}
function activeTeams(comp){return teamObjects(comp).filter(t=>isCompActive(comp))}""")
s=s.replace("const comp=$('competition').value, query=q.toLowerCase();const teams=teamObjects(comp).filter(t=>t.name.toLowerCase().includes(query));", "const comp=$('competition').value, query=q.toLowerCase();const teams=activeTeams(comp).filter(t=>t.name.toLowerCase().includes(query));")
s=s.replace("function renderTeams(){const q=($('teamSearch')?.value||'').toLowerCase(),c=$('teamCompetition')?.value||'all';let ts=teamObjects().filter(t=>!q||t.name.toLowerCase().includes(q));if(c!=='all')ts=ts.filter(t=>t.competition===c);", "function renderTeams(){const q=($('teamSearch')?.value||'').toLowerCase(),c=$('teamCompetition')?.value||'all';let ts=teamObjects().filter(t=>!q||t.name.toLowerCase().includes(q));if(c!=='all')ts=ts.filter(t=>teamCompetitions(t).includes(c));")
